import hashlib,json,os,re,stat,subprocess
from pathlib import Path
from datetime import datetime,timezone
p=Path('docs/planning/active/command-refactor');s=Path('/tmp/memq-projection-review.25rbrl');env=dict(os.environ,GIT_OPTIONAL_LOCKS='0')
def git(*args):return subprocess.check_output(['git',*args],env=env)
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def require(ok,msg):
 if not ok:raise RuntimeError(msg)
def meta(path):
 q=Path(path);v=q.lstat();d=dict(type=stat.S_IFMT(v.st_mode),mode=stat.S_IMODE(v.st_mode),size=v.st_size,mtime_ns=v.st_mtime_ns,ctime_ns=v.st_ctime_ns,birthtime=v.st_birthtime)
 if q.is_file():d['sha256']=sha(q)
 return d
idx=hashlib.sha256(git('ls-files','-s','-z')).hexdigest()
start=json.loads((s/'controller-start.json').read_text());require(idx==start['index_sha256'],'index drift');status=git('status','--porcelain=v1').decode();require(git('diff','--cached','--name-only')==b'','unexpected staged files')
require(git('rev-parse','HEAD').decode().strip()==start['head'],'HEAD drift');require(git('branch','--show-current').decode().strip()==start['branch'],'branch drift')
non_docs=[line[3:] for line in status.splitlines() if not line[3:].startswith('docs/')];require(set(non_docs)==set(start['dirty_hashes']),'unexpected non-documentation changes')
exports={x:meta(x) for x in start['exports']};require(exports==start['exports'],'ignored export metadata drift');require(sorted(str(x) for x in Path('exports').iterdir())==['exports/friday_context.txt','exports/friday_prompt.txt'],'ignored export membership drift')
f=p/'validation/memory-queries/preparation.json';require(sha(f)=='e6d203a0f87c92ddd7f3e1038a53c18b59cb01cdb56e89b9a3e84c086e78b593','original preparation modified');d=json.loads(f.read_text())
for group in ['programs','fixtures','receipts']:
 for name,e in d[group].items():
  require(hashlib.sha256(e['text'].encode()).hexdigest()==e['sha256'],group+' embedded '+name)
  if 'path' in e:require(sha(e['path'])==e['sha256'],group+' raw '+name)
for group in ['baseline','replay']:
 e=d[group];require(hashlib.sha256(e['text'].encode()).hexdigest()==e['sha256'],group+' hash')
for path,h in d['current_non_docs_hashes'].items():require(sha(path)==h,'protected source drift '+path)
for path,h in d['protected_dirty_hashes'].items():require(sha(path)==h,'dirty file drift '+path)
require(git('diff','--name-only','c5871054266da2340486d2043062c5fb95611c00','HEAD','--','packages','tests','scripts','AGENTS.md','README.md','main.py','pyproject.toml','uv.lock')==b'','committed product drift')
checks=json.loads((p/'validation/memory-queries/planning-checks.json').read_text())
for rel,h in checks['checks']['accepted_diag_evidence_unchanged'].items():require(sha(p/rel)==h,'accepted DIAG evidence '+rel)
projection=json.loads((p/'validation/memory-queries/record-projection-characterization.json').read_text());require(projection['case_count']==4,'projection count')
for name,e in projection['files'].items():require(hashlib.sha256(e['text'].encode()).hexdigest()==e['sha256'] and sha(e['path'])==e['sha256'],'supplemental evidence '+name)
for path,h in projection['source_files'].items():require(sha(path)==h,'characterized source '+path)
observations=json.loads(projection['files']['observations']['text']);require(len(observations['cases'])==4,'observation count')
require(not observations['application_network_or_real_store_calls'],'unexpected store use')
a=json.loads((p/'authority.json').read_text());m=a['memory_queries_preparation'];ids=json.loads((s/'finalized-identities.json').read_text())
for key,path in [('contract','memory-query-command-contract.md'),('directive','directives/CD-CMD-MEMQ-001-memory-queries.md'),('preparation','validation/memory-queries/preparation.json'),('projection','validation/memory-queries/record-projection-characterization.json'),('approval','approval/memory-queries.md')]:require(sha(p/path)==ids[key],'identity '+key)
require(m['contract_sha256']==ids['contract'] and m['directive_sha256']==ids['directive'] and m['approval_sha256']==ids['approval'],'authority pins')
require(m['construction_approval']=='granted' and m['decisions_approved']['MQ-D3'].startswith('R:'),'approved option R')
for name in ['README.md','next-phase.md','tactical-plan.md']:
 require('**Next gate:** '+ids['next_gate'] in (p/name).read_text(),'packet gate '+name)
require('next_gate: "'+ids['next_gate']+'"' in Path('docs/planning/board.yaml').read_text(),'board gate')
require(ids['next_gate'] in Path('docs/planning/README.md').read_text(),'dashboard gate')
# Exact directive frozen-input rows, not arbitrary prose hashes.
pins=re.findall(r'^\| `([^`]+)` \| `([a-f0-9]{64})` \|$',(p/'directives/CD-CMD-MEMQ-001-memory-queries.md').read_text(),re.M)
for rel,h in pins:require(sha(p/rel)==h,'directive input '+rel)
require((p/'execution-log.md').read_bytes().startswith(git('show','HEAD:docs/planning/active/command-refactor/execution-log.md')),'log is not append-only')
# Syntax-check the exact embedded shell blocks; no implementation is run.
blocks=re.findall(r'```sh\n(.*?)\n```',(p/'directives/CD-CMD-MEMQ-001-memory-queries.md').read_text(),re.S);shell=s/'directive-shell.zsh';shell.write_text('\n'.join(blocks)+'\n');subprocess.run(['zsh','-n',str(shell)],check=True,env=env)
subprocess.run(['git','diff','--check'],check=True,env=env)
report=dict(at=datetime.now(timezone.utc).isoformat(),status='passed',scope='controller planning/approval finalization only; no independent product validation',head=start['head'],index_sha256=idx,protected_non_docs=len(d['current_non_docs_hashes']),original_embedded_raw_receipts=len(d['receipts']),programs=len(d['programs']),fixtures=len(d['fixtures']),supplemental_legacy_cases=4,supplemental_embedded_raw_files=len(projection['files']),directive_frozen_inputs=len(pins),execution_log_append_only=True,directive_shell_syntax='zsh -n passed',ignored_exports=exports,dirty_hashes=start['dirty_hashes'],committed_product_diff_empty=True,non_docs_status=non_docs,identities=ids)
(s/'controller-verification.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k not in ['ignored_exports','identities']},indent=2))
